132	  it("is consistent under twenty permutations of periods, sources and object keys, with the trace in the fingerprint", () => {
133	    const twins = (): MaturityWallInput => ({...camil(), claimedSources: [...camil().claimedSources!, {...camil().claimedSources![0]!, id: "notas-comerciais-2026-b", claimedPeriod: "2027/28"}]});
134	    const first = diagnoseMaturityWall(twins());
135	    const permute = <T>(items: readonly T[], seed: number): T[] => { const copy = [...items]; let state = seed; for (let index = copy.length - 1; index > 0; index -= 1) { state = (state * 1103515245 + 12345) % 2147483648; const swap = state % (index + 1); [copy[index], copy[swap]] = [copy[swap]!, copy[index]!]; } return copy; };
136	    const reorderKeys = <T extends object>(value: T): T => Object.fromEntries(Object.entries(value).reverse()) as T;
137	    for (let seed = 1; seed <= 20; seed += 1) {
138	      const base = twins();
139	      const shuffled: MaturityWallInput = {...base, periods: permute(base.periods, seed).map(reorderKeys), claimedSources: permute(base.claimedSources!, seed + 1)};
140	      const again = diagnoseMaturityWall(seed % 2 ? reorderKeys(shuffled) : shuffled);
141	      expect(again.trace.inputFingerprint).toBe(first.trace.inputFingerprint);
142	      expect(again.trace.outputFingerprint).toBe(first.trace.outputFingerprint);
143	    }
144	  });
