  1	import {createHash} from "node:crypto";
  2	
  3	import {calculateLiquidityCoverage, maturityConcentration} from "@offroad/financial-core";
  4	import Decimal from "decimal.js";
  5	import {z} from "zod";
  6	
  7	/**
  8	 * Executor of the method `diagnose-maturity-wall` (v5, after the fourth independent review). Reads
  9	 * the ledger's schedule, names the walls against a versioned threshold (a share strictly above it),
 10	 * measures each period's cover sequentially through financial-core (cash carried forward, the
 11	 * generation declared for that period and nothing for a period without one, contracted sources),
 12	 * and says per period what depends on rollover or new debt. Interest enters the service only when
 13	 * the base states it per period; otherwise the cover is named as principal-only. A source of
 14	 * payment counts only with a contract and a disbursement in two documents of the base, never by a
 15	 * flag, and an unproven source is not placed in any period. The prior figure compares only when it
 16	 * is earlier, in the same unit and perimeter. The unit is anchored to the source that states it.
 17	 * Cash never goes below zero: once it is exhausted the next period opens at zero and the shortfall
 18	 * is carried separately as the cumulative deficit. A proven source must be contracted and disbursed
 19	 * after the reference date, otherwise it already sits inside the cash and would be counted twice.
 20	 * Negative amounts belong only to typed adjustment rows, never to a maturity bucket. An acceleration
 21	 * scenario, when the base holds the clause and the accelerable balance, is recorded apart from the
 22	 * contractual schedule and never added to it. Every number and every note keeps its anchor.
 23	 */
 24	const money = z.string().regex(/^-?\d+(\.\d+)?$/);
 25	const nonNegative = z.string().regex(/^\d+(\.\d+)?$/);
 26	const nonEmpty = z.string().trim().min(1);
 27	const isoDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/);
 28	const unitSchema = z.enum(["BRL", "BRL thousand", "BRL million", "USD", "USD thousand"]);
 29	const anchorSchema = z.object({document: nonEmpty, page: z.number().int().positive().optional(), note: nonEmpty.optional(), clause: nonEmpty.optional()}).strict();
 30	type Anchor = z.infer<typeof anchorSchema>;
 31	const compare = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
 32	
 33	const UNIT_WORDS: Record<z.infer<typeof unitSchema>, RegExp> = {"BRL": /\b(R\$|reais|BRL)\b(?!\s*(mil|milh))/i, "BRL thousand": /\b(mil|thousand)\b/i, "BRL million": /\b(milh[õo]es|million)\b/i, "USD": /\bUSD\b(?!\s*(mil|thousand))/i, "USD thousand": /\bUSD\b.*\b(mil|thousand)\b/i};
 34	const perimeterSchema = z.enum(["consolidated", "parent"]);
 35	
 36	export const maturityWallInputSchema = z.object({
 37	  referenceDate: isoDate,
 38	  unit: unitSchema,
 39	  /** Where the source states the unit; its note must name that unit, so a coherent rescale under another label is refused. */
 40	  unitAnchor: anchorSchema.extend({note: nonEmpty}),
 41	  perimeter: perimeterSchema.default("consolidated"),
 42	  /** Gross debt as the ledger reports it, with the ledger's unit: a rescaled schedule under the wrong label does not pass. */
 43	  grossDebt: z.object({value: nonNegative, unit: unitSchema, anchor: anchorSchema}).strict(),
 44	  /** The schedule as the note states it: buckets with an end date (null for open-ended buckets); the prior figure carries its own date and anchor. */
 45	  /** Maturity buckets carry non-negative amounts; an adjustment row (transaction costs) may be negative, belongs to no period and never enters the cover. */
