178	}).strict().superRefine((procedure, context) => {
179	  duplicateIssues(procedure.procedure.map((step) => step.id), ["procedure"], context);
180	  duplicateIssues(procedure.output.fields.map((field) => field.id), ["output", "fields"], context);
181	  duplicateIssues(procedure.dependencies, ["dependencies"], context);
182	  duplicateIssues(procedure.templates, ["templates"], context);
183	  duplicateIssues(procedure.knowledge.houseProcedureIds, ["knowledge", "houseProcedureIds"], context);
184	  duplicateIssues(procedure.knowledge.authorities, ["knowledge", "authorities"], context);
185	  duplicateIssues(procedure.knowledge.referenceDataKeys, ["knowledge", "referenceDataKeys"], context);
186	
187	  if (procedure.runtime.maxModelCalls === 0 && procedure.runtime.modelPurpose.length > 0) {
