200	    ["decisionRules", procedure.decisionRules],
201	    ["redFlags", procedure.redFlags],
202	    ["stopConditions", procedure.stopConditions],
203	  ];
204	  for (const [field, value] of candidateRequirements) {
205	    if (value.length === 0) context.addIssue({code: "custom", path: [field], message: `${procedure.maturity} procedures require ${field}`});
206	  }
207	
208	  const rank = maturityRank(procedure.maturity);
209	  if (rank >= maturityRank("implemented") && !procedure.implementation) {
210	    context.addIssue({code: "custom", path: ["implementation"], message: `${procedure.maturity} procedures require executable implementation evidence`});
211	  }
212	  if (rank >= maturityRank("ai_reviewed") && !procedure.reviews.some((review) => review.result !== "fail")) {
213	    context.addIssue({code: "custom", path: ["reviews"], message: `${procedure.maturity} procedures require a recorded independent review that passed or passed with conditions`});
214	  }
215	  if (rank >= maturityRank("tested")) {
216	    for (const kind of ["gold", "adversarial", "consistency"] as const) {
217	      if (procedure.testRuns[kind].length === 0) context.addIssue({code: "custom", path: ["testRuns", kind], message: `${procedure.maturity} procedures require recorded ${kind} runs`});
